/**
 * Safe utility to apply delta patches generated by Roamie to the itinerary tripData.
 * 
 * @param {object} currentTripData The existing tripData object from Firestore.
 * @param {object|null} patch The delta patch action sent by the AI.
 * @returns {object|null} The fully patched tripData copy, or null if invalid.
 */
export const applyTripPatch = (currentTripData, patch) => {
  if (!currentTripData || !patch || !patch.type) return null;
  
  const updated = JSON.parse(JSON.stringify(currentTripData));
  
  const getItineraryContainer = () => {
    if (updated.itinerary) return { parent: updated, key: "itinerary" };
    if (updated.day_wise_plan) return { parent: updated, key: "day_wise_plan" };
    if (updated.days) return { parent: updated, key: "days" };
    return null;
  };
  
  const itineraryInfo = getItineraryContainer();
  
  switch (patch.type) {
    case "UPDATE_DAY": {
      if (!itineraryInfo) break;
      const itinerary = itineraryInfo.parent[itineraryInfo.key];
      const { dayIndex, dayKey, dayData } = patch;
      
      if (Array.isArray(itinerary)) {
        const idx = typeof dayIndex === "number" ? dayIndex : parseInt(dayKey?.replace(/\D/g, "") || "0") - 1;
        if (idx >= 0 && idx < itinerary.length) {
          itinerary[idx] = { ...itinerary[idx], ...dayData };
        }
      } else if (itinerary && typeof itinerary === "object") {
        const key = dayKey || (typeof dayIndex === "number" ? `day_${dayIndex + 1}` : null);
        if (key && itinerary[key]) {
          itinerary[key] = { ...itinerary[key], ...dayData };
        }
      }
      break;
    }
    
    case "ADD_DAY": {
      if (!itineraryInfo) break;
      const itinerary = itineraryInfo.parent[itineraryInfo.key];
      const { dayData, dayKey } = patch;
      
      if (Array.isArray(itinerary)) {
        itinerary.push(dayData);
      } else if (itinerary && typeof itinerary === "object") {
        const nextDayNum = Object.keys(itinerary).length + 1;
        const key = dayKey || `day_${nextDayNum}`;
        itinerary[key] = dayData;
      }
      break;
    }
    
    case "REMOVE_DAY": {
      if (!itineraryInfo) break;
      const itinerary = itineraryInfo.parent[itineraryInfo.key];
      const { dayIndex, dayKey } = patch;
      
      if (Array.isArray(itinerary)) {
        const idx = typeof dayIndex === "number" ? dayIndex : parseInt(dayKey?.replace(/\D/g, "") || "0") - 1;
        if (idx >= 0 && idx < itinerary.length) {
          itinerary.splice(idx, 1);
        }
      } else if (itinerary && typeof itinerary === "object") {
        const key = dayKey || (typeof dayIndex === "number" ? `day_${dayIndex + 1}` : null);
        if (key && itinerary[key]) {
          delete itinerary[key];
          
          const sortedEntries = Object.entries(itinerary).sort(([a], [b]) => {
            const numA = parseInt(a.replace(/\D/g, "")) || 0;
            const numB = parseInt(b.replace(/\D/g, "")) || 0;
            return numA - numB;
          });
          
          const rekeyed = {};
          sortedEntries.forEach(([_, val], i) => {
            rekeyed[`day_${i + 1}`] = val;
          });
          itineraryInfo.parent[itineraryInfo.key] = rekeyed;
        }
      }
      break;
    }
    
    case "UPDATE_HOTELS": {
      const { hotels } = patch;
      if (Array.isArray(hotels)) {
        if (updated.hotel_options) updated.hotel_options = hotels;
        else if (updated.hotels) updated.hotels = hotels;
        else if (updated.accommodations) updated.accommodations = hotels;
        else updated.hotel_options = hotels;
      }
      break;
    }
    
    case "UPDATE_SUMMARY": {
      const { summary } = patch;
      if (updated.trip_summary) {
        updated.trip_summary = { ...updated.trip_summary, ...summary };
      } else if (updated.tripSummary) {
        updated.tripSummary = { ...updated.tripSummary, ...summary };
      } else {
        updated.trip_summary = summary;
      }
      break;
    }
    
    default:
      console.warn("Unknown patch type received from AI:", patch.type);
      return null;
  }
  
  return updated;
};
